import json
import os
import math
def task_func(json_data, output_dir=".", file_name="country_population_report.csv"):
    try:
        data = json.loads(json_data)
    except json.JSONDecodeError:
        raise ValueError("Malformed JSON data")

    if not data or not isinstance(data, list):
        raise ValueError("JSON data is empty or not a list")

    countries = []
    populations = []
    for entry in data:
        if not isinstance(entry, dict):
            raise ValueError("Each entry must be a dictionary")
        if 'country' not in entry or 'population' not in entry:
            raise ValueError("Missing required keys: 'country' or 'population'")
        country = entry['country']
        population = entry['population']
        if not isinstance(country, str):
            raise ValueError("Country name must be a string")
        if not isinstance(population, (int, float)) or population < 0:
            raise ValueError("Population must be a non-negative number")
        populations.append(math.floor(population))
        countries.append(country)

    df = pd.DataFrame({"Country": countries, "Population": populations})
    file_path = os.path.join(output_dir, file_name)
    try:
        df.to_csv(file_path, index=False)
    except Exception as e:
        raise IOError(f"Cannot write to file: {e}")

    return file_path, df
